# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

_VAR_REF_RE = re.compile(r"\$\{var\.([A-Za-z_][A-Za-z0-9_]*)\}")
_LTS_RE = re.compile(r"^\d+\.\d+\.x-scala\d+\.\d+$")
_LITERAL_CLUSTER_ID_RE = re.compile(r"^\d{4}-[0-9a-fA-F]{6,}-[A-Za-z0-9]+$")
REQUIRED_TAG_KEYS = {"data_product", "owner", "cost_center"}


def _first_job(job_yml: dict) -> dict:
    """Return the (only) job dict under `resources.jobs.<name>`."""
    jobs = (job_yml.get("resources") or {}).get("jobs") or {}
    assert jobs, f"Expected at least one job under resources.jobs; got {jobs!r}"
    # Per-dataset YAMLs emit a single job; take the first.
    return next(iter(jobs.values()))


def _walk(obj):
    """Yield every (key, value) pair found anywhere in a nested dict/list."""
    if isinstance(obj, dict):
        for k, v in obj.items():
            yield k, v
            yield from _walk(v)
    elif isinstance(obj, list):
        for item in obj:
            yield from _walk(item)


def _collect_var_refs(obj) -> set[str]:
    """Find every ${var.NAME} reference in any string value anywhere in obj."""
    found: set[str] = set()
    if isinstance(obj, str):
        found.update(_VAR_REF_RE.findall(obj))
    elif isinstance(obj, dict):
        for v in obj.values():
            found |= _collect_var_refs(v)
    elif isinstance(obj, list):
        for item in obj:
            found |= _collect_var_refs(item)
    return found


def _declared_vars(*yml_dicts: dict) -> set[str]:
    """Union of top-level keys under `variables:` across the given YAMLs."""
    names: set[str] = set()
    for d in yml_dicts:
        block = (d or {}).get("variables") or {}
        if isinstance(block, dict):
            names.update(block.keys())
    return names


