# ---------------------------------------------------------------------------
# DBX-BUNDLE-009 — DBR LTS pin on every cluster shape.
# ---------------------------------------------------------------------------

def test_dbr_lts_pin_on_complex_clusters(clusters_yml):
    """DBX-BUNDLE-009 — every complex cluster variable pins an LTS spark_version."""
    variables = clusters_yml.get("variables") or {}
    checked = 0
    variables_yml = _load(VARIABLES_YML)
    runtime_decl = ((variables_yml.get("variables") or {}).get("databricks_runtime_spark_version") or {})
    runtime_default = runtime_decl.get("default")
    for var_name, var_def in variables.items():
        if not isinstance(var_def, dict):
            continue
        if var_def.get("type") != "complex":
            continue
        default = var_def.get("default") or {}
        if "spark_version" not in default:
            continue
        spark_version = default["spark_version"]
        # `${var.databricks_runtime_spark_version}` indirection is allowed —
        # the indirected variable is asserted via variables.yml's default below.
        if isinstance(spark_version, str) and spark_version.startswith("${var."):
            assert isinstance(runtime_default, str) and _LTS_RE.match(runtime_default), (
                "variables.yml must declare databricks_runtime_spark_version.default "
                f"as an LTS DBR string; got {runtime_default!r}"
            )
            checked += 1
            continue
        assert isinstance(spark_version, str) and _LTS_RE.match(spark_version), (
            f"Cluster variable '{var_name}' has non-LTS spark_version "
            f"{spark_version!r}; must match {_LTS_RE.pattern} per DBX-BUNDLE-009"
        )
        checked += 1
    assert checked > 0, "Expected at least one complex cluster variable with spark_version"


