def test_main_job_existing_cluster_id_is_var_reference(main_job_yml):
    """DBX-DAB-005 — main job's existing_cluster_id, if present, must be ${var.…}."""
    job = _first_job(main_job_yml)
    # `existing_cluster_id` can appear at the job level or per-task; check all occurrences.
    occurrences = [v for k, v in _walk(job) if k == "existing_cluster_id"]
    assert occurrences, (
        "DBX-DAB-005 requires at least one existing_cluster_id reference in the main job"
    )
    for value in occurrences:
        assert isinstance(value, str), (
            f"existing_cluster_id must be a string ${{var.…}} reference; got {value!r}"
        )
        assert _VAR_REF_RE.search(value), (
            f"existing_cluster_id={value!r} must be a ${{var.…}} reference per DBX-DAB-005"
        )
        assert not _LITERAL_CLUSTER_ID_RE.match(value.strip()), (
            f"existing_cluster_id={value!r} looks like a literal cluster ID; "
            f"reference it via ${{var.…}} per DBX-DAB-005"
        )


# ---------------------------------------------------------------------------
# DBX-DAB-007 — ephemeral job_cluster allowed for DQ.
# ---------------------------------------------------------------------------

def test_dq_job_uses_ephemeral_job_cluster(dq_job_yml):
    """DBX-DAB-007 — DQ job declares job_clusters: keyed by ${var.…} and tasks reference it."""
    job = _first_job(dq_job_yml)
    job_clusters = job.get("job_clusters")
    assert isinstance(job_clusters, list) and job_clusters, (
        "DQ job must declare a job_clusters: block per DBX-DAB-007"
    )
    declared_keys: set[str] = set()
    for entry in job_clusters:
        assert isinstance(entry, dict), f"job_clusters entry must be a mapping; got {entry!r}"
        key = entry.get("job_cluster_key")
        assert key, "Each job_clusters entry must have a job_cluster_key"
        declared_keys.add(key)
        new_cluster = entry.get("new_cluster")
        assert isinstance(new_cluster, str) and _VAR_REF_RE.search(new_cluster), (
            f"new_cluster for '{key}' must be a ${{var.…}} reference (not an inline "
            f"cluster spec) per DBX-DAB-007; got {new_cluster!r}"
        )

    # At least one task must reference one of the declared job_cluster_keys.
    referenced = [v for k, v in _walk(job) if k == "job_cluster_key"]
    # Drop the keys declared on the entries themselves; we want task-side refs.
    task_refs = [v for v in referenced if v in declared_keys]
    assert task_refs, (
        f"No DQ task references job_cluster_key in {declared_keys!r} per DBX-DAB-007"
    )


