# ---------------------------------------------------------------------------
# Variable-declaration canary — every ${var.NAME} reference is declared.
# ---------------------------------------------------------------------------

def test_all_referenced_variables_are_declared(main_job_yml, dq_job_yml):
    """Every ${var.NAME} reference in the per-dataset job YAMLs must be declared in variables/*.yml.

    Catches `dbt_state_path`-style "referenced but not declared" bugs.
    """
    declared = _declared_vars(
        _load(VARIABLES_YML),
        _load(CLUSTERS_YML),
        *(_load(p) for p in PER_ENV_VARIABLES_YMLS if p.exists()),
    )
    # Targets inside databricks.yml also declare per-target variables — fold
    # those in so per-target overrides don't show up as "undeclared".
    targets = (_load(DATABRICKS_YML).get("targets") or {})
    for tgt in targets.values():
        if isinstance(tgt, dict):
            tgt_vars = tgt.get("variables") or {}
            if isinstance(tgt_vars, dict):
                declared.update(tgt_vars.keys())

    referenced = _collect_var_refs(main_job_yml) | _collect_var_refs(dq_job_yml)
    undeclared = referenced - declared
    assert not undeclared, (
        f"Variables referenced but not declared in variables/*.yml: {sorted(undeclared)}. "
        f"Declare each under variables.yml / clusters.yml or a per-target variables block."
    )
